                label = int(grid[r, c])
                val = grid[r, c]
                bbox = {'min_r': r, 'min_c': c, 'max_r': r, 'max_c': c, 'visited': [False]}

                # Find full bounding box
                for rr in range(r, grid.shape[0]):
                    for cc in range(c, grid.shape[1]):
                        if grid[rr, cc] == val:
                            if rr > bbox['max_r'] or (rr == bbox['max_r'] and cc > bbox['max_c']):
                                bbox['max_r'], bbox['max_c'] = rr, cc
                            if not np.all(visited[rr, cc]):
