                        if grid[rr, cc] != 0 and visited[rr, cc]:
                            if not visited[r][str(cc)][0]:
                                visited[r][str(cc)]['text'] = visited[r][str(cc)]['text'] + '|'
                            visited[r][str(cc)][0] = True

def extract_robust_info(grid):
    """Extract all robust info"""
    info = []
    visited = np.zeros(grid.shape, dtype=bool)

    for label in range(1, 9):
        positions = []
        for r in range(grid.shape[0]):
            for c in range(grid.shape[1]):
                if grid[r, c] == label and not visited[r, c]:
                    visited[r, c] = True
                    positions.append((r, c))
                    # Extend bbox
                    for rr in range(r, grid.shape[0]):
                        for cc in range(c, grid.shape[1]):
                            if grid[rr, cc] == label:
                                visited[rr, cc] = True

        if positions:
            min_r = min(p[0] for p in positions)
            min_c = min(p[1] for p in positions)
            max_r = max(p[0] for p in positions)
            max_c = max(p[1] for p in positions)

            info.append({
                'label': label,
                'positions': positions,
                'min_r': min_r,
                'min_c': min_c,
                'max_r': max_r,
                'max_c': max_c,
                'h': max_r - min_r + 1,
                'w': max_c - min_c + 1,
                'top_left': (min_r, min_c),
                'bbox': [(p[0], p[1]) for p in positions]
            })

    return info


